import { NextResponse } from "next/server";
import { createClient } from "@supabase/supabase-js";
import { z } from "zod";
import { createServerSupabase } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import { normalizeGhanaPhone } from "@/lib/phone";
import { networkSchema } from "@/lib/validation";
import { paystackBankCode,paystackRequest } from "@/lib/paystack";
const schema=z.object({momoNumber:z.string().min(9).max(20),momoNetwork:networkSchema,password:z.string().min(8).max(128)});
type PaystackResp={status:boolean;message:string;data:{subaccount_code?:string;account_number?:string;active?:boolean}};
export async function POST(request:Request){try{const supabase=await createServerSupabase();const {data:{user}}=await supabase.auth.getUser();if(!user)return NextResponse.json({error:"Please log in."},{status:401});const {data:profile}=await supabase.from("profiles").select("role,phone,full_name").eq("id",user.id).maybeSingle();if(profile?.role!=="vendor")return NextResponse.json({error:"Vendor access is required."},{status:403});const parsed=schema.safeParse(await request.json());if(!parsed.success)return NextResponse.json({error:"Enter your MoMo number, network and current password."},{status:400});const phone=normalizeGhanaPhone(parsed.data.momoNumber);if(!phone)return NextResponse.json({error:"Enter a 10-digit Ghana MoMo number, like 024 123 4567."},{status:400});const url=process.env.NEXT_PUBLIC_SUPABASE_URL;const anon=process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;if(!url||!anon)return NextResponse.json({error:"Account settings are unavailable right now."},{status:503});const verify=createClient(url,anon,{auth:{persistSession:false,autoRefreshToken:false}});const {error:authError}=await verify.auth.signInWithPassword({email:`${profile.phone}@users.seepay.shop`,password:parsed.data.password});if(authError)return NextResponse.json({error:"Your current password is not right."},{status:401});const db=createAdminClient();const {data:vendor,error:vendorError}=await db.from("vendors").select("id,business_name,paystack_subaccount_code").eq("owner_id",user.id).maybeSingle();if(vendorError||!vendor)return NextResponse.json({error:"Your shop record could not be found."},{status:404});if(!vendor.paystack_subaccount_code)return NextResponse.json({error:"Your shop's Mobile Money account is not set up yet."},{status:409});const result=await paystackRequest<PaystackResp>(`/subaccount/${encodeURIComponent(vendor.paystack_subaccount_code)}`,{business_name:vendor.business_name,bank_code:paystackBankCode(parsed.data.momoNetwork),account_number:phone,percentage_charge:0},"PUT");if(result.data?.active===false)return NextResponse.json({error:"Paystack could not verify that MoMo destination. Check the number and network."},{status:422});const {error:updateError}=await db.from("vendors").update({momo_number:phone,momo_network:parsed.data.momoNetwork}).eq("id",vendor.id);if(updateError)return NextResponse.json({error:"Paystack accepted the change, but your shop could not be updated. Contact support before trying again."},{status:500});return NextResponse.json({success:true});}catch(error){const message=error instanceof Error?error.message:"Payout details could not be updated.";return NextResponse.json({error:process.env.NODE_ENV==="production"?"Paystack could not verify those details. Check the number and network.":message},{status:400});}}
